begin;
create temp table reviewed_checkin_clients on commit drop as select c.id,c.user_id,c.name,c.checkin_frequency,c.end_date,d.id dispatch_id,d.sent_at,d.checkin_form_id from clients c join checkin_dispatches d on d.client_id=c.id where c.id in ('8553782c-e469-40c1-940e-1dca156e6d65'::uuid,'54b6e023-bfc5-4299-928a-b56b10a7dac0'::uuid,'7ed12247-3f96-4797-9f91-1e697dc5bf65'::uuid,'24ac22b1-6520-474d-95da-b76edf844969'::uuid,'5f718610-e763-43bf-8b29-918232a2e7b6'::uuid,'cd9241a7-d55c-4d1b-ba98-1aac762f022c'::uuid,'f3703ef1-4067-4b25-9a17-87bc18e26dd8'::uuid,'da2420ec-25f8-48fb-8445-8ccd060ec05f'::uuid,'ebd111ed-636c-4649-b305-a4024200682a'::uuid,'80d1e7d3-5502-4ba8-96c1-46a861529260'::uuid,'27a63ddf-3474-46c1-8275-39a18d6b158a'::uuid,'dbc0ab71-a399-4622-9980-b74a1c5d0518'::uuid,'4b6b57ea-1d67-457c-ae1f-e1feae923ff2'::uuid,'4b6ad1dc-45c2-4c1a-a01f-9c3f193b5630'::uuid,'d9b24bd7-cb1f-4424-9abd-8046e33b4731'::uuid,'8a13fd85-a059-4a1a-879b-16d60e6d661f'::uuid,'709ab4f4-5bd7-4a4e-8c11-cfefbc41de2f'::uuid,'8f897798-fd4e-47d5-8a0d-59e2c4f9e791'::uuid) and d.occurrence_date='2026-09-14' and d.status in ('sent','responded');
do $$ begin if (select count(*) from reviewed_checkin_clients)<>18 then raise exception 'Expected exactly 18 confirmed recipients'; end if; if (select count(*) from athlete_checkin_schedules where client_id in(select id from reviewed_checkin_clients))<>18 then raise exception 'Schedule count mismatch'; end if; end $$;
insert into checkin_configuration_changes(reason,table_name,row_id,before_config) select 'Rebase confirmed manual check-ins to 2026-09-14; automations remain paused','clients',id,to_jsonb(c) from clients c where id in(select id from reviewed_checkin_clients) or id='55bfec95-f9d0-4eea-b443-5282c6a86c19';
insert into checkin_configuration_changes(reason,table_name,row_id,before_config) select 'Rebase confirmed recipients; hold Mayra and stop Tarsis per admin','athlete_checkin_schedules',id,to_jsonb(s) from athlete_checkin_schedules s where client_id in(select id from reviewed_checkin_clients) or client_id in('8564c25d-e1c5-468d-9206-1a3f01e8437f','55bfec95-f9d0-4eea-b443-5282c6a86c19');
update clients set checkin_start_date='2026-09-14' where id in(select id from reviewed_checkin_clients);
update athlete_checkin_schedules s set start_date='2026-09-14',frequency_type=r.checkin_frequency,weekly_days=array[1],is_active=true,last_dispatched_at=r.sent_at from reviewed_checkin_clients r where s.client_id=r.id;
update athlete_checkin_schedules set is_active=false where client_id in('8564c25d-e1c5-468d-9206-1a3f01e8437f','55bfec95-f9d0-4eea-b443-5282c6a86c19');
update clients set has_checkin=false where id='55bfec95-f9d0-4eea-b443-5282c6a86c19';
insert into checkin_configuration_changes(reason,table_name,row_id,before_config) select 'Legacy unconfirmed dispatch superseded by confirmed manual check-in on 2026-09-14; not marked delivered','checkin_dispatches',id,to_jsonb(d) from checkin_dispatches d where id in('e41ed1c2-2f51-4e79-9237-241100711d6d','121f211e-a47b-49c9-bde5-70e08b3c42b5') and status='pending';
update checkin_dispatches set status='cancelled',metadata=coalesce(metadata,'{}')||jsonb_build_object('superseded_by_confirmed_cycle','2026-09-14','admin_review_reason','Old unconfirmed record retained, no retry') where id in('e41ed1c2-2f51-4e79-9237-241100711d6d','121f211e-a47b-49c9-bde5-70e08b3c42b5') and status='pending';
create temp table expected_checkin_dates on commit drop as select r.*,('2026-09-14'::date+n.days)::date next_date,s.send_time from reviewed_checkin_clients r join athlete_checkin_schedules s on s.client_id=r.id cross join lateral generate_series(case r.checkin_frequency when 'weekly' then 7 when 'biweekly' then 14 when 'monthly' then 28 end,r.end_date::date-'2026-09-14'::date,case r.checkin_frequency when 'weekly' then 7 when 'biweekly' then 14 when 'monthly' then 28 end) n(days);
insert into checkin_configuration_changes(reason,table_name,row_id,before_config) select 'Cancel obsolete pending dates after admin review on 2026-09-14','scheduled_checkins',s.id,to_jsonb(s) from scheduled_checkins s where s.status='pending' and ((s.client_id in('8564c25d-e1c5-468d-9206-1a3f01e8437f','55bfec95-f9d0-4eea-b443-5282c6a86c19') and s.scheduled_send_date>='2026-09-14') or (s.client_id in(select id from reviewed_checkin_clients) and not exists(select 1 from expected_checkin_dates e where e.id=s.client_id and e.next_date=s.scheduled_send_date)));
update scheduled_checkins s set status='cancelled',notes=concat_ws(E'\n',notes,'Revisão administrativa 14/09: ciclo substituído ou envio suspenso. Nenhuma mensagem enviada.') where s.status='pending' and ((s.client_id in('8564c25d-e1c5-468d-9206-1a3f01e8437f','55bfec95-f9d0-4eea-b443-5282c6a86c19') and s.scheduled_send_date>='2026-09-14') or (s.client_id in(select id from reviewed_checkin_clients) and not exists(select 1 from expected_checkin_dates e where e.id=s.client_id and e.next_date=s.scheduled_send_date)));
insert into scheduled_checkins(client_id,user_id,form_id,scheduled_send_date,scheduled_send_time,status,notes) select e.id,e.user_id,e.checkin_form_id,e.next_date,e.send_time,'pending','Ciclo confirmado a partir do envio manual de 14/09/2026. Automação pausada.' from expected_checkin_dates e where not exists(select 1 from scheduled_checkins s where s.client_id=e.id and s.scheduled_send_date=e.next_date);
do $$ begin if exists(select 1 from expected_checkin_dates e where (select count(*) from scheduled_checkins s where s.client_id=e.id and s.scheduled_send_date=e.next_date and s.status='pending')<>1) then raise exception 'Expected dates not represented exactly once'; end if; end $$;
select r.name,r.checkin_frequency,min(e.next_date) next_send,count(e.next_date) future_count,r.end_date from reviewed_checkin_clients r left join expected_checkin_dates e on e.id=r.id group by r.name,r.checkin_frequency,r.end_date order by r.name;
commit;
